package com.gwsheridan.worldsunwritten.release;

import com.google.gson.*;
import java.nio.file.*;
import java.util.*;

/** Creates new immutable example versions from verified authoring exports. */
public final class ReleaseCycle16Examples {
    public static void main(String[] args)throws Exception{Path root=Path.of(args[0]);String version=args[3];if(!version.matches("[0-9][a-zA-Z0-9._-]{0,39}"))throw new IllegalArgumentException("Invalid release");
        for(String item:List.of("creator-starters/single-block","creator-starters/layered","creator-starters/skyblock","creator-starters/custom-end","preset-studio/studio-partial","preset-studio/studio-skyblock","assembly-studio/assembly-demo","regional-terrain/regional-demo","procedural-pools/pool-demo","shared-regions/shared-regions","constrained-pools/constrained-pool","polygon-regions/polygon-regions","terrain-anchors/coastal-ruins","vertical-pools/vertical-tower","locked-archipelago/locked-archipelago")){int slash=item.indexOf('/');String dir=item.substring(0,slash),name=item.substring(slash+1);var files=ReleaseExamples.read(root.resolve("examples/"+dir+"/bundles/"+name+"-1.5.0.zip"));metadata(files,version,null,null);save(root,dir,name,version,files);}
        var composite=fresh(Path.of(args[1]),"composite_regions","composite_marker",version,"Composite regions","A concave region with a rectangular hole, shared by terrain and strict generation rules.");save(root,"composite-regions","composite-regions",version,composite);
        var themed=fresh(Path.of(args[2]),"themed_platform","themed_platform",version,"Themed platform","A supported starting platform with deterministic masonry and stair palettes, captured variants, supplies and a safe marker.");save(root,"structure-themes","themed-platform",version,themed);
        var plain=fresh(Path.of(args[2]),"foundation_platform","foundation_platform",version,"Foundation platform","An elevated platform on bounded stone footings. No palette or variant options are enabled.");String path="data/worldsunwritten_examples/worldgen/structure/foundation_platform.json";var definition=ReleaseExamples.json(plain.get(path));definition.remove("themes");plain.put(path,ReleaseExamples.bytes(definition));save(root,"structure-foundations","foundation-platform",version,plain);
        System.out.println("Prepared eighteen immutable example bundles and source resources.");
    }
    private static void save(Path root,String dir,String name,String version,SortedMap<String,byte[]> files)throws Exception{ReleaseExamples.save(files,root.resolve("examples/"+dir+"/bundles/"+name+"-"+version+".zip"),root.resolve("examples/"+dir+"/"+name+"-"+version+"-source"));}
    private static void metadata(Map<String,byte[]> files,String version,String title,String description){var manifest=ReleaseExamples.json(files.get("worldsunwritten.bundle.json"));manifest.addProperty("release",version);manifest.addProperty("author","GWSHERIDAN");if(title!=null)manifest.addProperty("title",title);if(description!=null)manifest.addProperty("description",description);for(var m:manifest.getAsJsonArray("required_mods"))if(m.getAsString().startsWith("wa_"))throw new IllegalArgumentException("An example requires a validation provider");files.put("worldsunwritten.bundle.json",ReleaseExamples.bytes(manifest));var pack=ReleaseExamples.json(files.get("pack.mcmeta"));pack.getAsJsonObject("pack").addProperty("description",manifest.get("title").getAsString()+" for Worlds Unwritten "+version);files.put("pack.mcmeta",ReleaseExamples.bytes(pack));}
    private static SortedMap<String,byte[]> fresh(Path archive,String presetName,String structureName,String version,String title,String description)throws Exception{var files=ReleaseExamples.read(archive);var manifest=ReleaseExamples.json(files.get("worldsunwritten.bundle.json"));String[] old=manifest.get("preset").getAsString().split(":",2);var preset=ReleaseExamples.json(files.remove("data/"+old[0]+"/worldgen/world_preset/"+old[1]+".json"));String path=files.keySet().stream().filter(p->p.contains("/worldgen/structure/")&&p.endsWith(".json")).findFirst().orElseThrow();String[] parts=path.split("/",5);String from=parts[1]+":"+parts[4].substring(0,parts[4].length()-5);replace(preset,from,"worldsunwritten_examples:"+structureName);var structure=ReleaseExamples.json(files.remove(path));for(var module:structure.getAsJsonArray("modules"))module.getAsJsonObject().getAsJsonObject("template").getAsJsonObject("worldsunwritten").addProperty("author","GWSHERIDAN");if(structure.has("themes"))for(var variant:structure.getAsJsonObject("themes").getAsJsonArray("variants"))variant.getAsJsonObject().getAsJsonObject("snapshot").getAsJsonObject("worldsunwritten").addProperty("author","GWSHERIDAN");files.put("data/worldsunwritten_examples/worldgen/structure/"+structureName+".json",ReleaseExamples.bytes(structure));files.put("data/worldsunwritten_examples/worldgen/world_preset/"+presetName+".json",ReleaseExamples.bytes(preset));manifest.addProperty("preset","worldsunwritten_examples:"+presetName);files.put("worldsunwritten.bundle.json",ReleaseExamples.bytes(manifest));metadata(files,version,title,description);return files;}
    private static void replace(JsonElement value,String from,String to){if(value.isJsonObject())for(var entry:value.getAsJsonObject().entrySet()){if(entry.getValue().isJsonPrimitive()&&entry.getValue().getAsJsonPrimitive().isString()&&entry.getValue().getAsString().equals(from))entry.setValue(new JsonPrimitive(to));else replace(entry.getValue(),from,to);}else if(value.isJsonArray())for(var child:value.getAsJsonArray())replace(child,from,to);}
}
